use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();
    
    // Parse arguments
    let mut base_ref = "main".to_string();
    let mut dry_run = false;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-b" | "--base-ref" => {
                i += 1;
                if i < args.len() { base_ref = args[i].clone(); }
            }
            "-n" | "--dry-run" => dry_run = true,
            "-h" | "--help" => { print_help(); return; }
            _ => {}
        }
        i += 1;
    }

    
    // Build the graph
    let dag = build_diff_review_graph();
    
    // Set up execution mode
    let mode = if dry_run {
        let mut mocks = BoundaryMocks::new();
        mocks.set_value("execute_diff", "response", Value::Response(gunbc_ir::transport::TransportResponse::Shell(gunbc_ir::transport::ShellResponse { exit_code: 0, stdout: "diff --git a/src/main.rs b/src/main.rs\n--- a/src/main.rs\n+++ b/src/main.rs\n@@ -1 +1,2 @@\n fn main() {}\n+// changed\n".to_string(), stderr: String::new() })));
        mocks.set_value("execute_llm", "response", Value::Response(gunbc_ir::transport::TransportResponse::Rest(gunbc_ir::transport::llm::mock::mock_openai_response("{\"findings\": [], \"summary\": \"No issues found.\"}"))));

        ExecutionMode::DryRun(mocks)
    } else {
        ExecutionMode::Real
    };
    
    // Print header
    println!("review");
    println!("  base_ref: {}", base_ref);

    println!("  mode: {}", if dry_run { "dry-run" } else { "real" });
    println!();
    
    // Execute
    match execute_with_mode(&dag, mode) {
        Ok(log) => {
            for entry in &log.entries {
                let marker = if entry.was_intercepted { " [DRY-RUN]" } else { "" };
                println!("[{}]{}", entry.node_id, marker);
                
                for (port, value) in &entry.outputs {
                    print_value(port, value);
                }
            }


        }
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    }
}

fn print_value(port: &str, value: &Value) {
    match value {
        Value::Str(s) => {
            // For stderr/stdout, print full output (important for debugging CI failures)
            if port.ends_with("stderr") || port.ends_with("stdout") {
                if !s.is_empty() {
                    println!("  {}: {}", port, s);
                }
            } else if s.len() < 80 {
                println!("  {}: {}", port, s);
            } else {
                println!("  {}: {}...", port, &s[..60.min(s.len())]);
            }
        }
        Value::Int(i) => println!("  {}: {}", port, i),
        Value::Bool(b) => println!("  {}: {}", port, b),
        Value::List(list) => println!("  {}: [{} items]", port, list.len()),
        Value::Map(map) => println!("  {}: {{{} entries}}", port, map.len()),
        Value::Json(_) => println!("  {}: <JSON>", port),
        _ => {}
    }
}

